const input=document.querySelector('[data-search-input]'),buttons=[...document.querySelectorAll('[data-filter]')],cards=[...document.querySelectorAll('[data-card]')],count=document.querySelector('[data-count]'),empty=document.querySelector('[data-empty]');let filter='all';function apply(){const q=input.value.trim().toLowerCase();let shown=0;for(const card of cards){const visible=(filter==='all'||card.dataset.category===filter)&&(!q||card.dataset.search.includes(q));card.hidden=!visible;if(visible)shown++}count.textContent=shown;empty.hidden=shown!==0}input.addEventListener('input',apply);for(const button of buttons)button.addEventListener('click',()=>{filter=button.dataset.filter;for(const b of buttons){const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))}apply()});
